		{"id":"b","priority":1,"release":2,"execution":3,"deadline":20},
		{"id":"c","priority":1,"release":2,"execution":3,"deadline":20}
	]}`
	first := postAnalyze(t, body).Body.String()
	for i := 0; i < 5; i++ {
		if got := postAnalyze(t, body).Body.String(); got != first {
